// Game speed: starts at 1x; faster speeds are unlocked through progress (data/speed.json).
// Pure and endless: 16x, 32x, 64x ... are generated by formula. Speed scales the simulation only
// (core/loop.js); saves, the real clock and offline progress never see it.
import SPEED from '../data/speed.json' with { type: 'json' };
import { upgradeLevel } from './shop.js';

export const FREE_SPEEDS = SPEED.free;
export const DEFAULT_SPEED = SPEED.default;
const G = SPEED.generated;
const MAX_LISTED = 200; // generated speeds are 2^k; 2^200 is far beyond anything meaningful (and still finite)

/** Rule for speed 2^k generated beyond the hand-made list. */
const generatedRule = (k) => ({ speed: 2 ** k, req: { kind: G.kind, value: G.base + G.step * (k - G.from) } });

/** Every locked-able speed in ascending order, lazily: hand-made first, then generated. */
export function speedRule(index) {
  if (index < SPEED.unlocks.length) return SPEED.unlocks[index];
  return generatedRule(G.from + (index - SPEED.unlocks.length));
}

export function requirementMet(state, req) {
  switch (req.kind) {
    case 'level':
      return state.level >= req.value;
    case 'rebirths':
      return (state.stats.rebirths || 0) >= req.value;
    case 'layerCount':
      return (state.layers[req.layer]?.count || 0) >= req.value;
    case 'tree':
      return (state.layers[req.layer]?.tree?.[req.node] || 0) >= req.level;
    case 'upgrade':
      return upgradeLevel(state, req.id) >= req.level;
    default:
      return false;
  }
}

export function describeReq(req) {
  switch (req.kind) {
    case 'level':
      return `Unlocks at level ${req.value}`;
    case 'rebirths':
      return `Unlocks after ${req.value} rebirth${req.value === 1 ? '' : 's'}`;
    case 'layerCount':
      return `Unlocks after ${req.value} prestige${req.value === 1 ? '' : 's'} of layer ${req.layer + 1}`;
    case 'tree':
      return `Unlocks with the rebirth-tree upgrade "${req.node}" (level ${req.level})`;
    case 'upgrade':
      return `Unlocks with the shop upgrade "${req.id}" (level ${req.level})`;
    default:
      return 'Locked';
  }
}

/** All speeds the player may use, ascending (free slow speeds, 1x, then every unlocked faster one). */
export function unlockedSpeeds(state) {
  const out = [...FREE_SPEEDS];
  for (let i = 0; i < MAX_LISTED; i++) {
    const r = speedRule(i);
    if (!requirementMet(state, r.req)) break; // later rules are never easier than earlier ones
    out.push(r.speed);
  }
  return out.sort((a, b) => a - b);
}

export const isUnlocked = (state, speed) => unlockedSpeeds(state).includes(Number(speed));

/** For the selector: free speeds, unlocked faster ones, then the next `lockedShown` locked ones with their requirement. */
export function speedOptions(state, lockedShown = 2) {
  const have = unlockedSpeeds(state);
  const opts = have.map((speed) => ({ speed, unlocked: true, note: speed < 1 ? 'slower (always available)' : '' }));
  let shown = 0;
  for (let i = 0; shown < lockedShown && i < MAX_LISTED; i++) {
    const r = speedRule(i);
    if (have.includes(r.speed)) continue;
    opts.push({ speed: r.speed, unlocked: false, note: describeReq(r.req), req: r.req });
    shown++;
  }
  return opts;
}

/** The speed the loop actually uses: the chosen one if unlocked, else the fastest unlocked speed below it (never above). */
export function effectiveSpeed(state) {
  const want = Number(state.settings.gameSpeed) || DEFAULT_SPEED;
  const have = unlockedSpeeds(state);
  if (have.includes(want)) return want;
  const below = have.filter((s) => s <= want);
  return below.length ? below[below.length - 1] : DEFAULT_SPEED;
}

export const fmtSpeed = (s) => `${Number(s)}×`;
